import{_ as t,o,c as a,a0 as n}from"./chunks/framework.BxrwG5q5.js";const h=JSON.parse('{"title":"Segments","description":"","frontmatter":{},"headers":[],"relativePath":"features/segments.md","filePath":"features/segments.md"}'),s={name:"features/segments.md"};function i(r,e,d,c,l,g){return o(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="segments" tabindex="-1">Segments <a class="header-anchor" href="#segments" aria-label="Permalink to &quot;Segments&quot;">​</a></h1><p>Segments are reusable audience groups that you can target across multiple feature flags and configs. Instead of duplicating conditions like &quot;plan equals enterprise AND country in US, UK&quot; on every flag, define it once as a segment and reference it everywhere.</p><h2 id="creating-a-segment" tabindex="-1">Creating a Segment <a class="header-anchor" href="#creating-a-segment" aria-label="Permalink to &quot;Creating a Segment&quot;">​</a></h2><ol><li>Go to <strong>Segments</strong> in the portal navigation</li><li>Click <strong>Create Segment</strong></li><li>Give it a name (e.g., &quot;Enterprise Users&quot;, &quot;Beta Testers&quot;)</li><li>Define conditions using attributes: <ul><li><code>plan</code> equals <code>enterprise</code></li><li><code>country</code> in_list <code>US, UK, DE</code></li><li><code>email</code> ends_with <code>@company.com</code></li></ul></li></ol><h2 id="condition-logic" tabindex="-1">Condition Logic <a class="header-anchor" href="#condition-logic" aria-label="Permalink to &quot;Condition Logic&quot;">​</a></h2><p>Segments use <strong>DNF (Disjunctive Normal Form)</strong>:</p><ul><li>Conditions within a group are <strong>AND</strong> (all must match)</li><li>Groups are connected by <strong>OR</strong> (any group matching is sufficient)</li></ul><p><strong>Example:</strong> &quot;Enterprise users in US/UK OR anyone with a @company.com email&quot;</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Group 1: plan equals &quot;enterprise&quot; AND country in_list &quot;US,UK&quot;</span></span>
<span class="line"><span>   OR</span></span>
<span class="line"><span>Group 2: email ends_with &quot;@company.com&quot;</span></span></code></pre></div><h2 id="using-segments-in-targeting" tabindex="-1">Using Segments in Targeting <a class="header-anchor" href="#using-segments-in-targeting" aria-label="Permalink to &quot;Using Segments in Targeting&quot;">​</a></h2><p>When creating a targeting rule on a config or feature flag:</p><ol><li>Click <strong>Target Segment</strong> (primary action)</li><li>Click the segment badges to select them</li><li>Set the value to serve for users in those segments</li><li>Multiple segments use OR logic — user in ANY selected segment gets the value</li></ol><h2 id="supported-operators" tabindex="-1">Supported Operators <a class="header-anchor" href="#supported-operators" aria-label="Permalink to &quot;Supported Operators&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Operator</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><code>equals</code></td><td>Exact match</td><td><code>plan</code> equals <code>&quot;pro&quot;</code></td></tr><tr><td><code>not_equals</code></td><td>Does not match</td><td><code>status</code> not_equals <code>&quot;banned&quot;</code></td></tr><tr><td><code>contains</code></td><td>Substring match</td><td><code>email</code> contains <code>&quot;@gmail&quot;</code></td></tr><tr><td><code>starts_with</code></td><td>Prefix match</td><td><code>user_id</code> starts_with <code>&quot;usr_&quot;</code></td></tr><tr><td><code>ends_with</code></td><td>Suffix match</td><td><code>email</code> ends_with <code>&quot;.edu&quot;</code></td></tr><tr><td><code>in_list</code></td><td>Any in comma-separated list</td><td><code>country</code> in_list <code>&quot;US,UK,DE&quot;</code></td></tr><tr><td><code>not_in_list</code></td><td>None in list</td><td><code>plan</code> not_in_list <code>&quot;free,trial&quot;</code></td></tr><tr><td><code>greater_than</code></td><td>Numeric greater</td><td><code>age</code> greater_than <code>18</code></td></tr><tr><td><code>less_than</code></td><td>Numeric less</td><td><code>login_count</code> less_than <code>5</code></td></tr><tr><td><code>regex_match</code></td><td>Regular expression</td><td><code>email</code> regex_match <code>&quot;.*@corp\\\\.com$&quot;</code></td></tr></tbody></table><h2 id="segment-usage-tracking" tabindex="-1">Segment Usage Tracking <a class="header-anchor" href="#segment-usage-tracking" aria-label="Permalink to &quot;Segment Usage Tracking&quot;">​</a></h2><p>The portal shows which configs reference each segment. This helps you understand the impact before modifying or deleting a segment.</p><h2 id="how-segments-work-with-api-keys" tabindex="-1">How Segments Work with API Keys <a class="header-anchor" href="#how-segments-work-with-api-keys" aria-label="Permalink to &quot;How Segments Work with API Keys&quot;">​</a></h2><ul><li><strong>Client keys (cid_):</strong> The API evaluates segment membership server-side. Your segment conditions are never exposed to the browser.</li><li><strong>Server keys (svr_):</strong> Segment definitions are included in the API response for local evaluation by the SDK.</li></ul>`,18)])])}const m=t(s,[["render",i]]);export{h as __pageData,m as default};
